class Solution:
    def reverse(self, x: int) -> int:
        sign = -1 if x < 0 else 1
        remaining = abs(x)
        limit = 2 ** 31 if sign < 0 else 2 ** 31 - 1
        result = 0
        while remaining:
            remaining, digit = divmod(remaining, 10)
            if result > (limit - digit) // 10:
                return 0
            result = result * 10 + digit
        return sign * result
